          "code": "{\n  \"name\": \"classdock-local\",\n  \"private\": true,\n  \"scripts\": {\n    \"build:spellcheck-worker\": \"node tools/build-korean-spell-worker.mjs\",\n    \"build:manual\": \"node tools/build-manual-html.mjs\",\n    \"check:manual\": \"node tools/build-manual-html.mjs --check\",\n    \"build\": \"npm run build:spellcheck-worker && npm run build:manual && node build-offline.js\",\n    \"lint\": \"eslint src/js tests tools desktop *.js\",\n    \"check\": \"npm run lint && node tools/check-source.js\",\n    \"test\": \"node --test tests/*.test.js\",\n    \"test:e2e\": \"playwright test\",\n    \"release-check\": \"node tools/check-release.js\",\n    \"verify\": \"npm run check && npm test && npm run build && npm run release-check\"\n  },\n  \"devDependencies\": {\n    \"@playwright/test\": \"^1.55.0\",\n    \"esbuild\": \"0.25.8\",\n    \"eslint\": \"^10.8.1\",\n    \"globals\": \"^17.11.0\"\n  },\n  \"dependencies\": {\n    \"@xterm/xterm\": \"^6.0.0\",\n    \"hunspell-dict-ko\": \"0.1.0\",\n    \"hunspell-wasm\": \"0.3.0\"\n  }\n}\n",
